package com.fixmer.mared.technology.workspace;
import com.fixmer.genesis.technology.editor.CodeSyntaxLexer;
import com.fixmer.mared.Mared;import com.fixmer.mared.gui2.framework.screen.MaredScreen;import com.fixmer.mared.gui2.framework.components.editor.*;import com.fixmer.genesis.technology.workspace.*;
import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;
import java.util.*;import java.util.concurrent.*;import java.nio.charset.StandardCharsets;
/** Explicit-save shared editor. Local dirty buffers survive file switches, conflicts and reconnect screens. */
public final class WorkspaceScreen112 extends MaredScreen {
 private final Screen previous;private final WorkspaceClient112 client=new WorkspaceClient112();
 private final Map<String,WorkspaceDraft112> drafts=new LinkedHashMap<>();private final Map<String,String> checkpointed=new HashMap<>();
 private final Map<String,EditorDocument> documents=new HashMap<>();private final Map<String,EditorHistory> histories=new HashMap<>();private final Map<String,EditorView> views=new HashMap<>();
 private static final Map<String,WorkspaceDraft112> RECOVERY=new LinkedHashMap<>(32,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,WorkspaceDraft112> e){return size()>256;}};
 private static final ThreadPoolExecutor CACHE_IO=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(128),r->{var t=new Thread(r,"Genesis-workspace-drafts112");t.setDaemon(true);return t;});
 private EditBox name,path;private MaredMultiLineEditBox editor;private Button save,create,choose,newFile,files,refresh,remote,members,copy;
 private String project="",store="",role="VIEWER",active="",savedName="",savedPath="",titleText="",notice="",queuedProject,queuedFile,queuedPath;private boolean updating,canCreate,remoteReload;private long projectRevision,lastPoll,lastCache;private int left,w;
 private List<String> fileRows=List.of();private Map<String,String> metadata=Map.of();
 public WorkspaceScreen112(Screen previous){super(tr("title"));this.previous=previous;}public static Component tr(String key,Object...args){return Component.translatable("mared.workspace112."+key,args);}
 private Button button(String key,int x,int y,int width,Runnable action){return addRenderableWidget(Button.builder(tr(key),b->action.run()).bounds(x,y,Math.max(1,width),20).build());}
 private WorkspaceDraft112 draft(){return drafts.get(active);}private String key(String file){return store+"/"+project+"/"+file;}
 @Override protected void init(){
  if(name!=null)savedName=name.getValue();if(path!=null)savedPath=path.getValue();client.attach();w=Math.max(1,Math.min(960,width-20));left=(width-w)/2;
  if(width<320||height<240){button("back",left,height-26,w,this::onClose);return;}
  int input=Math.max(70,w-202);name=addRenderableWidget(new EditBox(font,left,42,input,20,tr("project_name")));name.setMaxLength(64);name.setValue(savedName);name.setHint(tr("project_name"));
  create=button("create",left+input+4,42,96,()->send("CREATE","","",name.getValue(),0,"","","",this::opened));choose=button("projects",left+input+104,42,w-input-104,this::chooseProject);
  int pw=Math.max(70,w-238);path=addRenderableWidget(new EditBox(font,left,68,pw,20,tr("path")));path.setMaxLength(120);path.setValue(savedPath);path.setHint(Component.literal("src/Example.java"));
  newFile=button("new_file",left+pw+4,68,74,()->send("NEW",path.getValue(),"","",0,"","","",this::receivedFile));files=button("files",left+pw+82,68,74,this::chooseFile);refresh=button("refresh",left+pw+160,68,w-pw-160,this::refresh);
  int bw=(w-16)/5;save=button("save",left,94,bw,this::save);remote=button("remote",left+bw+4,94,bw,this::reload);copy=button("copy",left+2*(bw+4),94,bw,()->{if(draft()!=null)minecraft.keyboardHandler.setClipboard(draft().text());});members=button("members",left+3*(bw+4),94,bw,()->{checkpoint();minecraft.setScreen(new WorkspaceMembersScreen112(this,client,project,metadata));});button("back",left+4*(bw+4),94,w-4*(bw+4),this::onClose);
  editor=addRenderableWidget(new MaredMultiLineEditBox(left,141,w,Math.max(30,height-194),0xFF9B71E8,this::changed));
  if(queuedProject!=null){project=queuedProject;queuedProject=null;active="";fileRows=List.of();metadata=Map.of();attach();view();}else if(queuedFile!=null){String id=queuedFile,p=queuedPath;queuedFile=null;attach();read(p,id);}else{attach();if(remoteReload&&draft()!=null){remoteReload=false;reloadNow();}else refresh();}tick();
 }
 private void changed(){if(!updating&&editor!=null&&draft()!=null)draft().edit(editor.getValue());}
 private void attach(){if(editor==null)return;updating=true;try{var d=draft();if(d==null){editor.setValue("");editor.setEditable(false);return;}var doc=documents.computeIfAbsent(active,k->{var v=new EditorDocument();v.setValue(d.text());return v;});if(!doc.getValue().equals(d.text())){int l=doc.cursorLine(),c=doc.cursorCol();doc.setValue(d.text());doc.setCursor(l,c);histories.computeIfAbsent(active,k->new EditorHistory()).clear();}var view=views.computeIfAbsent(active,k->new EditorView());view.setSpanResolver(new CodeSyntaxSpanResolver(CodeSyntaxLexer.languageFor(d.path()),false,0xFFDDDDDD));editor.attachDocument(doc,histories.computeIfAbsent(active,k->new EditorHistory()),view);}finally{updating=false;}}
 private void send(String op,String path,String file,String text,long revision,String target,String role,String other,java.util.function.Consumer<Map<String,String>> done){
  try{boolean catalog=Set.of("CREATE","LIST").contains(op);client.send(WorkspaceClient112.request(op,catalog?"":project,path,file,text,revision,catalog?0:projectRevision,target,role,other),d->{if("DENIED".equals(d.get("result")))this.role="NONE";else if(d.containsKey("role"))this.role=d.get("role");if(d.containsKey("projectRevision"))projectRevision=Long.parseLong(d.get("projectRevision"));if(d.containsKey("store")){if(!store.isEmpty()&&!store.equals(d.get("store"))){notice="STORE_CHANGED";return;}store=d.get("store");}done.accept(d);});}catch(RuntimeException bad){client.result=text.getBytes(StandardCharsets.UTF_8).length>WorkspaceWire112.MAX_TEXT?"LIMIT":"INVALID";}
 }
 private void opened(Map<String,String> d){if(!d.containsKey("project"))return;checkpoint();project=d.get("project");titleText=d.getOrDefault("title","");active="";fileRows=List.of();metadata=d;attach();view();}
 private void refresh(){if(client.busy())return;if(project.isEmpty())send("LIST","","","",0,"","","",d->canCreate="true".equals(d.get("canCreate")));else view();}
 private void chooseProject(){if(client.busy())return;send("LIST","","","",0,"","","",d->{canCreate="true".equals(d.get("canCreate"));var choices=new ArrayList<WorkspacePickerScreen112.Item>();for(String row:d.getOrDefault("projects","").split("\n")){String[] p=row.split("\\|",3);if(p.length==3)choices.add(new WorkspacePickerScreen112.Item(p[2]+" · "+tr("role."+p[1]).getString(),()->{checkpoint();queuedProject=p[0];titleText=p[2];role=p[1];}));}if(!choices.isEmpty())minecraft.setScreen(new WorkspacePickerScreen112(this,tr("projects"),choices));});}
 private void view(){send("VIEW","","","",0,"","","",d->{if(!d.containsKey("files"))return;metadata=d;titleText=d.getOrDefault("title",titleText);fileRows=d.get("files").lines().filter(x->!x.isBlank()).toList();if(draft()!=null){var row=fileRows.stream().map(x->x.split("\\|",3)).filter(x->x.length==3&&x[0].equals(draft().id())).findFirst();if(row.isPresent())read(row.get()[2],row.get()[0]);else notice="REMOVED";}});}
 private void chooseFile(){if(client.busy()||fileRows.isEmpty())return;var choices=new ArrayList<WorkspacePickerScreen112.Item>();for(String row:fileRows){String[] p=row.split("\\|",3);if(p.length==3){var d=drafts.get(key(p[0]));choices.add(new WorkspacePickerScreen112.Item(p[2]+(d!=null&&d.dirty()?" *":""),()->{queuedFile=p[0];queuedPath=p[2];}));}}minecraft.setScreen(new WorkspacePickerScreen112(this,tr("files"),choices));}
 private void read(String name,String id){send("READ",name,id,"",0,"","","",this::receivedFile);}
 private void receivedFile(Map<String,String> d){if(!d.containsKey("text"))return;String id=d.get("file"),p=d.get("path"),k=key(id);long revision=Long.parseLong(d.get("revision"));var value=drafts.get(k);
  if(value==null){value=new WorkspaceDraft112(id,p,revision,d.get("text"));try{var cached=RECOVERY.get(account()+"/"+k);if(cached==null)cached=cache().load(account(),UUID.fromString(store),UUID.fromString(project),UUID.fromString(id));if(cached!=null&&cached.dirty()){value=new WorkspaceDraft112(cached.id(),cached.path(),cached.revision(),cached.base());value.edit(cached.text());notice="RECOVERED";}}catch(Exception bad){notice="CACHE_ERROR";Mared.LOGGER.warn("[Workspace112] Draft load failed",bad);}drafts.put(k,value);}
  value.remote(p,revision,d.get("text"));var rows=new ArrayList<>(fileRows);rows.removeIf(x->x.startsWith(id+"|"));rows.add(id+"|"+revision+"|"+p);fileRows=List.copyOf(rows);active=k;path.setValue(p);attach();
 }
 private boolean exists(){return draft()!=null&&fileRows.stream().anyMatch(x->x.startsWith(draft().id()+"|"));}
 public Map<String,String> selectedFile(){var d=draft();return d==null?Map.of():Map.of("path",d.path(),"file",d.id(),"revision",Long.toString(d.revision()));}
 private void save(){var d=draft();if(d==null||!exists()||!d.dirty()||d.conflict())return;String k=active,submitted=d.text();long expected=d.revision();send("SAVE",d.path(),d.id(),submitted,expected,"","","",answer->{if(answer.containsKey("text")){var same=drafts.get(k);if(same!=null){same.acknowledged(expected,submitted,Long.parseLong(answer.get("revision")),answer.get("text"));notice="";checkpoint();}}else if("CONFLICT".equals(answer.get("result")))notice="CONFLICT";});}
 private void reload(){if(draft()==null||client.busy())return;minecraft.setScreen(new ConfirmScreen(yes->{remoteReload=yes;minecraft.setScreen(this);},tr("remote"),tr("replace_confirm")));}
 private void reloadNow(){var d=draft();if(d==null)return;send("READ",d.path(),d.id(),"",0,"","","",answer->{if(answer.containsKey("text")){d.replaceWithRemote(answer.get("path"),Long.parseLong(answer.get("revision")),answer.get("text"));notice="";attach();checkpoint();}});}
 private UUID account(){return Minecraft.getInstance().getUser().getProfileId();}private WorkspaceDraftCache112 cache(){return new WorkspaceDraftCache112(Minecraft.getInstance().gameDirectory.toPath().resolve("config/mared/workspace-drafts112"));}
 private void checkpoint(){for(var e:drafts.entrySet()){String k=e.getKey();var d=e.getValue();String fingerprint=d.revision()+"\n"+d.base()+"\n"+d.text();if(fingerprint.equals(checkpointed.get(k)))continue;var snapshot=new WorkspaceDraft112(d.id(),d.path(),d.revision(),d.base());snapshot.edit(d.text());String[] scope=k.split("/",3);UUID account=account();var cache=cache();RECOVERY.put(account+"/"+k,snapshot);
   try{CACHE_IO.execute(()->{try{cache.save(account,UUID.fromString(scope[0]),UUID.fromString(scope[1]),snapshot);}catch(Exception bad){Mared.LOGGER.warn("[Workspace112] Draft checkpoint failed",bad);Minecraft.getInstance().execute(()->{checkpointed.remove(k);notice="CACHE_ERROR";});}});checkpointed.put(k,fingerprint);}catch(RejectedExecutionException busy){notice="CACHE_ERROR";}}
 }
 @Override public void tick(){client.tick();if(editor==null||width<320||height<240)return;long now=System.nanoTime();if(now-lastCache>800_000_000L){lastCache=now;checkpoint();}if(now-lastPoll>2_000_000_000L&&!client.busy()&&client.connected()){lastPoll=now;refresh();}boolean idle=client.connected()&&!client.busy(),edit=idle&&Set.of("OWNER","MANAGER","EDITOR").contains(role),writable=client.connected()&&Set.of("OWNER","MANAGER","EDITOR").contains(role)&&draft()!=null;if(editor.isEditable()!=writable)editor.setEditable(writable);save.active=edit&&draft()!=null&&exists()&&draft().dirty()&&!draft().conflict();create.active=idle&&canCreate;choose.active=idle;newFile.active=edit&&!project.isEmpty();files.active=idle&&!fileRows.isEmpty();refresh.active=idle;remote.active=idle&&draft()!=null;copy.active=draft()!=null;members.active=idle&&!project.isEmpty();}
 @Override public boolean keyPressed(int key,int scan,int modifiers){if((modifiers&2)!=0&&key==83){save();return true;}return super.keyPressed(key,scan,modifiers);}@Override public boolean isPauseScreen(){return false;}
 @Override public void removed(){checkpoint();client.detach();}
 @Override public void onClose(){if(drafts.values().stream().anyMatch(WorkspaceDraft112::dirty))minecraft.setScreen(new ConfirmScreen(yes->{if(yes){checkpoint();client.detach();minecraft.setScreen(previous);}else minecraft.setScreen(this);},tr("back"),tr("close_confirm")));else{client.detach();minecraft.setScreen(previous);}}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xFF13161E);g.drawCenteredString(font,title,width/2,8,0xFFFFFFFF);if(width<320||height<240){g.drawCenteredString(font,tr("resize"),width/2,40,0xFFDDDDDD);super.render(g,mx,my,dt);return;}g.drawString(font,font.plainSubstrByWidth(tr("status."+(client.connected()?client.result:"DISCONNECTED")).getString(),w),left,25,0xFFCCD0DC,false);var d=draft();String caption=titleText+" · "+(d==null?tr(project.isEmpty()?"select_project":"select_file").getString():d.path()+" · r"+d.revision()+(d.dirty()?" *":"")+" · "+d.text().getBytes(StandardCharsets.UTF_8).length+"/16384 B"+(d.conflict()?" · "+tr("status.CONFLICT").getString():""));g.drawString(font,font.plainSubstrByWidth(caption,w),left,126,0xFFDDDDDD,false);g.drawString(font,font.plainSubstrByWidth(tr("role_label",tr("role."+role)).getString(),w),left,height-44,0xFFCCD0DC,false);if(!notice.isEmpty())g.drawString(font,font.plainSubstrByWidth(tr("status."+notice).getString(),w),left,height-29,0xFFE4BC78,false);super.render(g,mx,my,dt);}
}
